import 'package:flutter_local_notifications/flutter_local_notifications.dart';
import 'package:timezone/data/latest.dart' as tz;
import 'package:timezone/timezone.dart' as tz;

class NotificationService {
  static final FlutterLocalNotificationsPlugin _plugin =
      FlutterLocalNotificationsPlugin();

  // 알림 탭 시 호출되는 콜백
  static void Function(String?)? onNotificationTap;

  /// 초기화 - main()에서 호출
  static Future<void> init() async {
    // timezone 초기화
    tz.initializeTimeZones();
    tz.setLocalLocation(tz.getLocation('Asia/Seoul'));

    // Android 설정
    const androidSettings = AndroidInitializationSettings('@mipmap/ic_launcher');

    // iOS 설정
    const iosSettings = DarwinInitializationSettings(
      requestAlertPermission: true,
      requestBadgePermission: true,
      requestSoundPermission: true,
    );

    const initSettings = InitializationSettings(
      android: androidSettings,
      iOS: iosSettings,
    );

    await _plugin.initialize(
      initSettings,
      onDidReceiveNotificationResponse: _onNotificationResponse,
    );

    // Android 알림 채널 생성
    await _createNotificationChannel();
  }

  /// 알림 채널 생성 (Android 8.0+)
  static Future<void> _createNotificationChannel() async {
    const channel = AndroidNotificationChannel(
      'default_channel',
      '기본 알림',
      description: '앱의 기본 알림 채널',
      importance: Importance.high,
      playSound: true,
    );

    await _plugin
        .resolvePlatformSpecificImplementation<
            AndroidFlutterLocalNotificationsPlugin>()
        ?.createNotificationChannel(channel);
  }

  /// 알림 응답 처리
  static void _onNotificationResponse(NotificationResponse response) {
    final payload = response.payload;
    if (payload != null && onNotificationTap != null) {
      onNotificationTap!(payload);
    }
  }

  /// 권한 요청 (Android 13+, iOS)
  static Future<bool> requestPermission() async {
    // Android
    final androidPlugin = _plugin.resolvePlatformSpecificImplementation<
        AndroidFlutterLocalNotificationsPlugin>();
    final granted = await androidPlugin?.requestNotificationsPermission();

    // iOS는 초기화 시 자동 요청됨
    return granted ?? true;
  }
}

// NotificationService 클래스에 추가

  /// 즉시 알림 표시
  static Future<void> showNotification({
    required int id,
    required String title,
    required String body,
    String? payload,
  }) async {
    const androidDetails = AndroidNotificationDetails(
      'default_channel',  // 채널 ID
      '기본 알림',          // 채널 이름
      channelDescription: '앱의 기본 알림',
      importance: Importance.high,
      priority: Priority.high,
      icon: '@mipmap/ic_launcher',
      playSound: true,
      enableVibration: true,
    );

    const iosDetails = DarwinNotificationDetails(
      presentAlert: true,
      presentBadge: true,
      presentSound: true,
    );

    const details = NotificationDetails(
      android: androidDetails,
      iOS: iosDetails,
    );

    await _plugin.show(id, title, body, details, payload: payload);
  }

  /// 진행 바가 있는 알림 (다운로드 등)
  static Future<void> showProgressNotification({
    required int id,
    required String title,
    required int progress,
    required int maxProgress,
  }) async {
    final androidDetails = AndroidNotificationDetails(
      'progress_channel',
      '진행 알림',
      channelDescription: '다운로드 등 진행 상황 알림',
      importance: Importance.low,
      priority: Priority.low,
      showProgress: true,
      maxProgress: maxProgress,
      progress: progress,
      ongoing: true,  // 스와이프로 삭제 불가
      autoCancel: false,
    );

    final details = NotificationDetails(android: androidDetails);
    await _plugin.show(id, title, '$progress%', details);
  }

  /// 알림 취소
  static Future<void> cancelNotification(int id) async {
    await _plugin.cancel(id);
  }

  /// 모든 알림 취소
  static Future<void> cancelAllNotifications() async {
    await _plugin.cancelAll();
  }

// NotificationService 클래스에 추가

  /// 특정 시간에 알림 예약
  static Future<void> scheduleNotification({
    required int id,
    required String title,
    required String body,
    required DateTime scheduledTime,
    String? payload,
  }) async {
    const androidDetails = AndroidNotificationDetails(
      'scheduled_channel',
      '예약 알림',
      channelDescription: '예약된 알림',
      importance: Importance.high,
      priority: Priority.high,
    );

    const iosDetails = DarwinNotificationDetails(
      presentAlert: true,
      presentBadge: true,
      presentSound: true,
    );

    const details = NotificationDetails(
      android: androidDetails,
      iOS: iosDetails,
    );

    // DateTime을 TZDateTime으로 변환
    final tzScheduledTime = tz.TZDateTime.from(scheduledTime, tz.local);

    await _plugin.zonedSchedule(
      id,
      title,
      body,
      tzScheduledTime,
      details,
      payload: payload,
      androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
      matchDateTimeComponents: null,  // 일회성 알림
    );
  }

  /// 매일 특정 시간에 반복 알림
  static Future<void> scheduleDailyNotification({
    required int id,
    required String title,
    required String body,
    required int hour,
    required int minute,
    String? payload,
  }) async {
    const androidDetails = AndroidNotificationDetails(
      'daily_channel',
      '매일 알림',
      channelDescription: '매일 반복되는 알림',
      importance: Importance.high,
      priority: Priority.high,
    );

    const details = NotificationDetails(android: androidDetails);

    // 다음 알림 시간 계산
    final now = tz.TZDateTime.now(tz.local);
    var scheduledDate = tz.TZDateTime(
      tz.local,
      now.year,
      now.month,
      now.day,
      hour,
      minute,
    );

    // 이미 지난 시간이면 내일로 설정
    if (scheduledDate.isBefore(now)) {
      scheduledDate = scheduledDate.add(const Duration(days: 1));
    }

    await _plugin.zonedSchedule(
      id,
      title,
      body,
      scheduledDate,
      details,
      payload: payload,
      androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
      matchDateTimeComponents: DateTimeComponents.time,  // 매일 같은 시간
    );
  }

  /// 매주 특정 요일, 시간에 반복 알림
  static Future<void> scheduleWeeklyNotification({
    required int id,
    required String title,
    required String body,
    required int weekday,  // 1=월요일, 7=일요일
    required int hour,
    required int minute,
    String? payload,
  }) async {
    const androidDetails = AndroidNotificationDetails(
      'weekly_channel',
      '주간 알림',
      channelDescription: '매주 반복되는 알림',
      importance: Importance.high,
      priority: Priority.high,
    );

    const details = NotificationDetails(android: androidDetails);

    // 다음 해당 요일 계산
    var scheduledDate = _nextInstanceOfWeekday(weekday, hour, minute);

    await _plugin.zonedSchedule(
      id,
      title,
      body,
      scheduledDate,
      details,
      payload: payload,
      androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
      matchDateTimeComponents: DateTimeComponents.dayOfWeekAndTime,
    );
  }

  /// 다음 특정 요일 계산 헬퍼
  static tz.TZDateTime _nextInstanceOfWeekday(int weekday, int hour, int minute) {
    final now = tz.TZDateTime.now(tz.local);
    var scheduledDate = tz.TZDateTime(
      tz.local,
      now.year,
      now.month,
      now.day,
      hour,
      minute,
    );

    while (scheduledDate.weekday != weekday || scheduledDate.isBefore(now)) {
      scheduledDate = scheduledDate.add(const Duration(days: 1));
    }

    return scheduledDate;
  }

  /// 예약된 알림 목록 조회
  static Future<List<PendingNotificationRequest>> getPendingNotifications() async {
    return await _plugin.pendingNotificationRequests();
  }

import 'package:flutter/material.dart';
import 'services/notification_service.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // 알림 서비스 초기화
  await NotificationService.init();

  // 알림 탭 핸들러 설정
  NotificationService.onNotificationTap = (payload) {
    // payload에 따라 특정 화면으로 이동
    debugPrint('알림 탭됨: $payload');
    // Navigator.pushNamed(context, '/detail', arguments: payload);
  };

  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: '알림 예제',
      home: const NotificationDemo(),
    );
  }
}

class NotificationDemo extends StatefulWidget {
  const NotificationDemo({super.key});

  @override
  State<NotificationDemo> createState() => _NotificationDemoState();
}

class _NotificationDemoState extends State<NotificationDemo> {
  @override
  void initState() {
    super.initState();
    _requestPermission();
  }

  Future<void> _requestPermission() async {
    final granted = await NotificationService.requestPermission();
    if (!granted) {
      // 권한 거부 시 처리
      debugPrint('알림 권한이 거부되었습니다');
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('알림 테스트')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            ElevatedButton(
              onPressed: () async {
                await NotificationService.showNotification(
                  id: 1,
                  title: '안녕하세요!',
                  body: '이것은 즉시 알림입니다.',
                  payload: 'instant_notification',
                );
              },
              child: const Text('즉시 알림 보내기'),
            ),
            const SizedBox(height: 12),
            ElevatedButton(
              onPressed: () async {
                final scheduledTime = DateTime.now().add(
                  const Duration(seconds: 5),
                );
                await NotificationService.scheduleNotification(
                  id: 2,
                  title: '예약 알림',
                  body: '5초 후에 도착한 알림입니다!',
                  scheduledTime: scheduledTime,
                  payload: 'scheduled_notification',
                );
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('5초 후 알림 예약됨')),
                );
              },
              child: const Text('5초 후 알림 예약'),
            ),
            const SizedBox(height: 12),
            ElevatedButton(
              onPressed: () async {
                await NotificationService.scheduleDailyNotification(
                  id: 3,
                  title: '매일 리마인더',
                  body: '오늘의 할 일을 확인하세요!',
                  hour: 9,
                  minute: 0,
                  payload: 'daily_reminder',
                );
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('매일 오전 9시 알림 설정됨')),
                );
              },
              child: const Text('매일 오전 9시 알림 설정'),
            ),
            const SizedBox(height: 12),
            ElevatedButton(
              onPressed: () async {
                final pending = await NotificationService.getPendingNotifications();
                showDialog(
                  context: context,
                  builder: (context) => AlertDialog(
                    title: const Text('예약된 알림'),
                    content: Text('총 ${pending.length}개의 알림이 예약되어 있습니다.'),
                    actions: [
                      TextButton(
                        onPressed: () => Navigator.pop(context),
                        child: const Text('확인'),
                      ),
                    ],
                  ),
                );
              },
              child: const Text('예약된 알림 확인'),
            ),
            const SizedBox(height: 12),
            ElevatedButton(
              onPressed: () async {
                await NotificationService.cancelAllNotifications();
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('모든 알림 취소됨')),
                );
              },
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.red,
                foregroundColor: Colors.white,
              ),
              child: const Text('모든 알림 취소'),
            ),
          ],
        ),
      ),
    );
  }
}
